<?php
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/image_upload.php';$db=(new Database())->getConnection();if(!$db){fwrite(STDERR,"Database unavailable\n");exit(1);}
$used=[];foreach(['SELECT image_url path FROM products','SELECT image_url path FROM product_images','SELECT logo_url path FROM seller_profiles','SELECT cover_url path FROM seller_profiles','SELECT banner_url path FROM seller_profiles','SELECT image_url path FROM promotional_banners','SELECT evidence_image path FROM return_requests'] as $sql){try{foreach($db->query($sql)->fetchAll(PDO::FETCH_COLUMN) as $path)if($path)$used[(string)$path]=true;}catch(Throwable $ignored){}}
$root=realpath(__DIR__.'/../assets/images');$deleted=0;if(!$root){exit(0);}foreach(['products','stores','banners','returns'] as $kind){$dir=$root.DIRECTORY_SEPARATOR.$kind.DIRECTORY_SEPARATOR.'uploads';if(!is_dir($dir))continue;foreach(new DirectoryIterator($dir) as $file){if(!$file->isFile()||$file->getMTime()>time()-86400)continue;$relative='assets/images/'.$kind.'/uploads/'.$file->getFilename();if(!isset($used[$relative])){deleteManagedUpload($relative);$deleted++;}}}echo "deleted=$deleted\n";
